public static class Appearance1112RestoreCheck {public static string Run(){if(Application.isPlaying)throw new Exception("Edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);for(int rig=0;rig<2;rig++){var root="Assets/Resources/MeshyNative/SourceParts/Rig"+rig+"/";var face=AssetDatabase.LoadAssetAtPath<Mesh>(root+"Part_Face_NEUTRAL_00.asset");var hair=AssetDatabase.LoadAssetAtPath<Mesh>(root+"Part_Hair_BOB_00.asset");if(face.triangles.Length/3!=9658||hair.triangles.Length/3!=34186)throw new Exception("Restore triangle mismatch");}return "SourceParts original faces9658/hair34186 confirmed for both rigs; Edit mode";}}
